/// The weight of a script, relative to one Latin letter.
pub fn weight_of(script: &str) -> f64 {
    match script {
        "arabic" => 1.5,
        "armenian" => 1.0,
        "cjk" => 3.0,
        "cyrillic" => 1.0,
        "default" => 1.0,
        "digit" => 3.5,
        "ethiopic" => 3.0,
        "georgian" => 1.0,
        "greek" => 1.0,
        "hangul" => 2.5,
        "hebrew" => 1.5,
        "indic" => 1.8,
        "kana" => 2.2,
        "khmer_myanmar" => 1.8,
        "latin" => 1.0,
        "mark" => 0.0,
        "punctuation" => 0.5,
        "space" => 0.2,
        "thai_lao" => 1.5,
        "yi" => 3.0,
        _ => 1.0,
    }
}

